134		private ApiClient getApiClient() {
135	
136			if (!integrationEnabled) {
137				throw new CamundaClientException("Integrazione con Camunda BPMN Engine disabilitata.");
138			}
139	
140			OkHttpClient httpClient = new OkHttpClient.Builder().authenticator(new Authenticator() {
141	
142				@Override
143				public Request authenticate(Route route, Response response) throws IOException {
144					String credential = Credentials.basic(username, password);
145					return response.request().newBuilder().header("Authorization", credential).build();
146				}
147			}).build();
148	
149			ApiClient client = new ApiClient(httpClient);
150			client.setBasePath(apiBasePath);
151			client.setConnectTimeout(connectionTimeout);
152			client.setReadTimeout(readTimeout);
153	
154			return client;
155		}
