272		@Override
273		public String startProcessInstance(String tenantId, String processDefinitionTenantId, String processDefinitionKey, String businessKey, Map<String, Object> variables) {
274			ProcessDefinitionApi api = new ProcessDefinitionApi(getApiClient());
275	
276			try {
277				StartProcessInstanceDto startProcessInstanceDto = new StartProcessInstanceDto();
278				startProcessInstanceDto.setBusinessKey(businessKey);
279	
280				if (variables != null) {
281					Map<String, VariableValueDto> variablesMap = new HashMap<String, VariableValueDto>();
282					for (Entry<String, Object> entry : variables.entrySet()) {
283						String key = entry.getKey();
284						Object value = entry.getValue();
285	
286						VariableValueDto variableValueDto = new VariableValueDto();
287						if (value instanceof Date) {
288							value = simpleDateFormat.format(value);
289							variableValueDto.setType("date");
290						}
291						else {
292							variableValueDto.setType(value.getClass().getSimpleName().toLowerCase());
293						}
294						variableValueDto.setValue(value);
295	
296						variablesMap.put(key, variableValueDto);
297					}
298	
299					// Add tenant ID
300					if (tenantId != null) {
301						VariableValueDto tenantIdVariableValueDto = new VariableValueDto();
302						tenantIdVariableValueDto.setValue(tenantId);
303						variablesMap.put("tenantId", tenantIdVariableValueDto);
304					}
305	
306					startProcessInstanceDto.setVariables(variablesMap);
307				}
308	
309				ProcessInstanceWithVariablesDto processInstanceWithVariablesDto = null;
310				if (processDefinitionTenantId != null) {
311					processInstanceWithVariablesDto = api.startProcessInstanceByKeyAndTenantId(processDefinitionKey, processDefinitionTenantId, startProcessInstanceDto);
312				}
313				else {
314					processInstanceWithVariablesDto = api.startProcessInstanceByKey(processDefinitionKey, startProcessInstanceDto);
315				}
316	
317				return processInstanceWithVariablesDto.getId();
318			}
319			catch (ApiException e) {
320				log.error("startProcessInstance: " + e.getResponseBody(), e);
321				throw new CamundaClientException("startProcessInstance :: " + e.getResponseBody(), e);
322			}
323		}
