326		public String insertOrUpdateProcessDefinitions(String tenantId, String fileName, byte[] byteArray) throws CamundaClientException {
327	
328			File file = null;
329			File tempFolder = null;
330			String deploymentId = "";
331			DeploymentWithDefinitionsDto output = null;
332	
333			try {
334	
335				ApiClient client = getApiClient();
336	
337				String time = "_" + new Date().getTime();
338	
339				String suffix = ".bpmn";
340	
341				Path tempDirWithPrefix = Files.createTempDirectory(null);
342	
343				tempFolder = tempDirWithPrefix.toFile();
344	
345				Path path = Paths.get(tempDirWithPrefix.toString(), fileName + time + suffix);
346	
347				Path filePath = Files.write(path, byteArray);
348	
349				file = filePath.toFile();
350	
351				DeploymentApi deploymentApi = new DeploymentApi(client);
352				output = deploymentApi.createDeployment(tenantId, null, false, false, "AutoDeployment", null, file);
353	
354				deploymentId = output.getId();
355	
356				log.debug("Created " + output.getId());
357	
358			}
359			catch (ApiException e) {
360				log.error("insertOrUpdateProcessDefinitions: " + e.getResponseBody(), e);
361				throw new CamundaClientException("insertOrUpdateProcessDefinitions :: " + e.getResponseBody(), e);
362			}
363			catch (Exception e) {
364				log.error("insertOrUpdateProcessDefinitions: " + e.getMessage(), e);
365				throw new CamundaClientException("insertOrUpdateProcessDefinitions :: " + e.getMessage(), e);
366			}
367			finally {
368				if (null != file) {
369					file.delete();
370				}
371				if (null != tempFolder) {
372					tempFolder.delete();
373				}
374			}
375	
376			return deploymentId;
377		}
