457		private TaskQueryDto getTaskQueryDtoIstanzeBandi(List<String> tenantId, List<String> candidateGroups, String codiceServizio,String codiceBando,Boolean unassigned, List<VariableQueryParameter> variableQueryParameters,
458														 String sortName, String sortOrder, String sortType, String assignee) {
459			TaskQueryDto q = new TaskQueryDto();
460	
461			if (Validator.isNotNull(unassigned) && unassigned) {
462				q.setUnassigned(Boolean.TRUE);
463			}
464	
465			if (Validator.isNotNull(tenantId)) {
466				q.setTenantIdIn(tenantId);
467			}
468	
469			if (null != candidateGroups && !candidateGroups.isEmpty()) {
470				q.setCandidateGroups(candidateGroups);
471			}
472	
473			List<VariableQueryParameterDto> vqs = new ArrayList<>();
474	
475			if (Validator.isNotNull(variableQueryParameters)) {
476				for (VariableQueryParameter v : variableQueryParameters) {
477					VariableQueryParameterDto vq = new VariableQueryParameterDto();
478					vq.setName(v.getName());
479					vq.setValue(v.getValue());
480					vq.setOperator(VariableQueryParameterDto.OperatorEnum.fromValue(v.getOperator().getValue()));
481	
482					vqs.add(vq);
483				}
484			}
485	
486			if (Validator.isNotNull(codiceServizio)) {
487				VariableQueryParameterDto vq = new VariableQueryParameterDto();
488				vq.setName(CustomProcessVariables.CODICE_SERVIZIO);
489				vq.setValue(codiceServizio);
490				vq.setOperator(VariableQueryParameterDto.OperatorEnum.EQ);
491				vqs.add(vq);
492			}
493	
494			if (Validator.isNotNull(codiceBando)) {
495				VariableQueryParameterDto vq = new VariableQueryParameterDto();
496				vq.setName(CustomProcessVariables.CODICE_BANDO);
497				vq.setValue(codiceBando);
498				vq.setOperator(VariableQueryParameterDto.OperatorEnum.EQ);
499				vqs.add(vq);
500			}
501	
502			if (!vqs.isEmpty()) {
503				q.setProcessVariables(vqs);
504			}
505	
506			if (Validator.isNotNull(sortName) && Validator.isNotNull(sortOrder) && Validator.isNotNull(sortType)) {
507	
508				TaskQueryDtoSorting sort = new TaskQueryDtoSorting();
509				sort.setSortBy(TaskQueryDtoSorting.SortByEnum.PROCESSVARIABLE);
510				sort.setSortOrder(TaskQueryDtoSorting.SortOrderEnum.fromValue(sortOrder));
511	
512				SortTaskQueryParametersDto p = new SortTaskQueryParametersDto();
513				p.setVariable(sortName);
514				p.setType(sortType);
515	
516				sort.setParameters(p);
517	
518				q.setSorting(Arrays.asList(sort));
519			}
520	
521			if (Validator.isNotNull(assignee)) {
522				q.setAssignee(assignee);
523			}
524	
525			q.setVariableValuesIgnoreCase(true);
526			return q;
527		}
