162	
163					for (DomandaBando domanda : domandeBando) {
164						avviaProcesso(domanda);
165					}
166				} catch (Exception e) {
167					_log.error("Fermato avvii processi per bando " + bando.getCodice(), e);
168				}
169			}
170		}
