172		private void avviaProcesso(DomandaBando domanda) throws Exception {
173			ObjectMapper objectMapper = new ObjectMapper();
174	
175			long businessKey = domanda.getDomandaBandoId();
176			if (Validator.isNotNull(domanda.getProcessInstanceId())) {
177				throw new Exception("Esiste già una istanza di processo assegnata alla richiesta: " + businessKey);
178			}
179	
180			// verifica processo già avviato
181			long groupId = domanda.getGroupId();
182	
183			Organization siteOrganization = organizationUtility.getSiteOrganization(groupId);
184	
185			long organizationId = siteOrganization.getOrganizationId();
186	
187			String tenantId = String.valueOf(organizationId);
188			boolean existProcessByBusinessKey = camundaClient.existProcessByBusinessKey(tenantId, String.valueOf(businessKey));
189	
190			if (existProcessByBusinessKey) {
191				throw new Exception("Esiste già una istanza di processo attiva per organizationId " + organizationId + " e businessKey " + businessKey);
192			}
193	
194			User userRichiesta = userLocalService.getUserByScreenName(domanda.getCompanyId(), domanda.getCodiceFiscale().toLowerCase());
195	
196			PrincipalThreadLocal.setName(userRichiesta.getUserId());
197			PermissionChecker permissionChecker = PermissionCheckerFactoryUtil.create(userRichiesta);
198			PermissionThreadLocal.setPermissionChecker(permissionChecker);
199	
200			Organization organization = organizationLocalService.getOrganization(organizationId);
201			Serializable codiceIPACustomAttribute = organization.getExpandoBridge().getAttribute(OrganizationCustomAttributes.CODICE_IPA.getNomeAttributo());
202	
203			String codiceIPA = null;
204			if (codiceIPACustomAttribute != null) {
205				codiceIPA = (String) codiceIPACustomAttribute;
206			}
207	
208			Bando bando = bandoLocalService.getBando(domanda.getBandoId());
209			long processoId = bando.getProcessoId();
210			if (Validator.isNull(processoId)) {
211				throw new Exception("Impossibile avviare il workflow: Processo BPM mancante.");
212			}
213	
214			Processo processo = processoLocalService.fetchProcesso(processoId);
215			if (Validator.isNull(processo) || !processo.isAttivo()) {
216				throw new Exception("Impossibile avviare il workflow: Processo NON trovato.");
217			}
218	
219			List<SottoOrganizzazione> sottoOrganizzazioni = sottoOrganizzazioneLocalService.getListSottoOrganizzazioneByBandoId(domanda.getBandoId());
220			if (sottoOrganizzazioni != null) {
221				for (SottoOrganizzazione sottoOrganizzazione : sottoOrganizzazioni) {
222					String candidateGroup = String.valueOf(sottoOrganizzazione.getSubOrganizationId());
223					boolean existsGroup = camundaClient.existsGroup(candidateGroup);
224					if (!existsGroup) {
225						throw new Exception("Impossibile assegnare il Gruppo Destinatario.");
226					}
227				}
228			}
229	
230			// Allegati
231			String allegatiJson = "";
232			List<AllegatoDomandaBando> allegatiDomanda = allegatoDomandaBandoLocalService.getListaAllegatiByDomandaBandoId(domanda.getDomandaBandoId());
233			List<FileAllegato> datiFileAllegati = getAllegati(allegatiDomanda);
234			if (datiFileAllegati != null) {
235				allegatiJson = objectMapper.writerWithDefaultPrettyPrinter().writeValueAsString(datiFileAllegati);
236			}
237	
238			// PDF principale
239			String pdfFirmatoJson = "";
240			List<AllegatoDomandaBando> allegatiDomandaByDomandaBandoIdPrincipale = allegatoDomandaBandoLocalService.getListaAllegatiByDomandaBandoIdAndPrincipale(domanda.getDomandaBandoId(),
241					true);
242	
243			if (allegatiDomandaByDomandaBandoIdPrincipale != null && !allegatiDomandaByDomandaBandoIdPrincipale.isEmpty()) {
244				AllegatoDomandaBando allegatoPrincipaleBando = allegatiDomandaByDomandaBandoIdPrincipale.get(0);
245				FileAllegato allegatoPrincipale = getAllegatoPrincipale(allegatoPrincipaleBando);
246				if (allegatoPrincipale != null) {
247					pdfFirmatoJson = objectMapper.writerWithDefaultPrettyPrinter().writeValueAsString(allegatoPrincipale);
248				}
249			}
250	
251			Map<String, Object> variables = new HashMap<>();
252			variables.put(GestioneBandiCommonConstants.ID_DOMANDA_BANDO, domanda.getDomandaBandoId());
253			for (SottoOrganizzazione sottoOrganizzazione : sottoOrganizzazioni) {
254				String candidateGroup = String.valueOf(sottoOrganizzazione.getSubOrganizationId());
255				variables.put(sottoOrganizzazione.getCodice(), candidateGroup);
256			}
257	
258			// Termini
259			List<TermineBando> listaTermineBando = termineBandoLocalService.getTermineBandoByBandoId(domanda.getBandoId());
260			for (TermineBando termineBando : listaTermineBando) {
261				if (Validator.isNotNull(termineBando.getDataScadenza())) {
262					SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'");
263					String dataScadenza = sdf.format(termineBando.getDataScadenza());
264					variables.put(termineBando.getCodice(), dataScadenza);
265				} else {
266					variables.put(termineBando.getCodice(), convertiSecondiInISO8601(termineBando.getSecondi()));
267				}
268			}
269			List<DomandaBandoDatoAggiuntivo> domandaBandoDatoAggiuntivos = domandaBandoDatoAggiuntivoLocalService.getDomandaBandoDatoAggiuntivoByDomandaBandoIdAndChiave(List.of(domanda.getDomandaBandoId()),
270					List.of(DatoAggiuntivoChiave.CHIUSURA_NEGATIVA_AUTOMATICA.name()));
271	
272			if(ListUtil.isNotNull(domandaBandoDatoAggiuntivos) && ListUtil.isNotEmpty(domandaBandoDatoAggiuntivos)){
273				if(Validator.isNotNull(domandaBandoDatoAggiuntivos.get(0))){
274					DomandaBandoDatoAggiuntivo domandaBandoDatoAggiuntivo = domandaBandoDatoAggiuntivos.get(0);
275	
276					if(Validator.isNotNull(domandaBandoDatoAggiuntivo.getValore()) && domandaBandoDatoAggiuntivo.getValore().equalsIgnoreCase(Boolean.TRUE.toString())){
277						variables.put(GestioneBandiCommonConstants.CHIUSURA_NEGATIVA_AUTOMATICA, Boolean.TRUE.toString());
278						variables.put(CustomProcessVariables.ESITO_PROCEDIMENTO, "NEGATIVO");
279					}
280				}
281			}
282	
283			//TODO: aggiungere le variabili necessarie
284			//variables.put("ESITO_LAVORAZIONE","CONCESSIONE");
285	
286			TipologiaBando tipologiaBando = tipologiaBandoLocalService.getTipologiaBando(bando.getTipologiaBandoId());
287			variables.put(GestioneBandiCommonConstants.TIPOLOGIA_BANDO_DOMANDA, tipologiaBando.getCodice());
288	
289			variables.put(CustomProcessVariables.DENOMINAZIONE_RICHIEDENTE, userRichiesta.getFullName());
290			variables.put(CustomProcessVariables.COD_FISCALE_RICHIEDENTE, domanda.getCodiceFiscale().toUpperCase());
291			variables.put(CustomProcessVariables.EMAIL_RICHIEDENTE, domanda.getEmail());
292			variables.put(CustomProcessVariables.PARTITA_IVA_RICHIEDENTE, domanda.getPartitaIva());
293	
294	//									variables.put(CustomProcessVariables.FILE_ALLEGATI, allegatiJson);
295			variables.put(CustomProcessVariables.NOME_FILE_FIRMATO, ALLEGATO_PDF_FIRMATO);
296			variables.put(CustomProcessVariables.PDF_FIRMATO, pdfFirmatoJson);
297	
298			variables.put(CustomProcessVariables.CODICE_IPA_COMUNE, codiceIPA);
299			variables.put(CustomProcessVariables.DENOMINAZIONE_COMUNE, organization.getName());
300	
301			variables.put(GestioneBandiCommonConstants.DATA_CREAZIONE_DOMANDA, domanda.getCreateDate());
302			variables.put(GestioneBandiCommonConstants.STATO_DOMANDA, domanda.getStato());
303			variables.put(GestioneBandiCommonConstants.INVIO_GUEST, String.valueOf(domanda.getInvioGuest()));
304			variables.put(GestioneBandiCommonConstants.RAGIONE_SOCIALE, domanda.getRagioneSociale());
305			variables.put(GestioneBandiCommonConstants.DATA_CREAZIONE_DOMANDA_SEARCH, domanda.getCreateDate().getTime());
306			variables.put(GestioneBandiCommonConstants.DATA_INVIO_DOMANDA, domanda.getDataArrivo());
307			variables.put(GestioneBandiCommonConstants.DATA_INVIO_DOMANDA_SEARCH, domanda.getDataArrivo().getTime());
308			variables.put(CustomProcessVariables.TIPO_INTEGRAZIONE, "");
309			variables.put(CustomProcessVariables.CODICE_BANDO, bando.getCodice());
310	
311			variables.put(GestioneBandiCommonConstants.CODICE_AOO, bando.getCodiceAOO());
312			variables.put(GestioneBandiCommonConstants.CODICE_UO, bando.getCodiceUO());
313	
314			variables.put(GestioneBandiCommonConstants.PROTOCOLLA_INTEGRAZIONI, bando.getProtocollaIntegrazioni());
315			variables.put(CustomProcessVariables.CAMBIO_STATO_WORKFLOW, true);
316			variables.put(GestioneBandiCommonConstants.SUPPORTA_CHIUDI_PRATICA_ESITO_NEGATIVO, true);
317	
318			String processDefinitionTenantId = tenantId;
319	
320			boolean isBackofficeMainSiteProcess = siteUtility.isBackofficeMainSite(processo.getGroupId(), processo.getCompanyId());
321	
322			if (isBackofficeMainSiteProcess) {
323				processDefinitionTenantId = null;
324			}
325	
326			String processInstanceId = camundaClient.startProcessInstance(tenantId, processDefinitionTenantId, processo.getCodice(), String.valueOf(businessKey), variables);
327			domandaBandoLocalService.updateProcessInstanceIdDomandaBando(domanda.getDomandaBandoId(), processInstanceId);
328		}
