438		/**
439		 * getStorageType: Utility method to get the storage type from the scheduler entry wrapper.
440		 *
441		 * @return StorageType The storage type to use.
442		 */
443		protected StorageType getStorageType() {
444			if (_schedulerEntryImpl instanceof StorageTypeAware) {
445				return ((StorageTypeAware) _schedulerEntryImpl).getStorageType();
446			}
447	
448			return StorageType.MEMORY_CLUSTERED;
449		}
