135			if (richieste != null && !richieste.isEmpty()) {
136				ObjectMapper objectMapper = new ObjectMapper();
137				for (Richiesta richiesta : richieste) {
138	
139					try {
140						Procedura procedura = null;
141						long businessKey = richiesta.getRichiestaId();
142						if (Validator.isNotNull(richiesta.getProcessInstanceId())) {
143							_log.debug("Esiste già una istanza di processo assegnata alla richiesta: " + businessKey);
144							continue;
145						}
146	
147						// verifica processo già avviato
148						long groupId = richiesta.getGroupId();
149	
150						Organization siteOrganization = organizationUtility.getSiteOrganization(groupId);
151	
152						long organizationId = siteOrganization.getOrganizationId();
153	
154						String tenantId = String.valueOf(organizationId);
155						boolean existProcessByBusinessKey = camundaClient.existProcessByBusinessKey(tenantId, String.valueOf(businessKey));
156	
157						if (existProcessByBusinessKey) {
158							_log.debug("Esiste già una istanza di processo attiva per organizationId " + organizationId + " e businessKey " + businessKey);
159							continue;
160						}
161	
162						long proceduraId = richiesta.getProceduraId();
163						long subOrganizationId = richiesta.getSubOrganizationId();
164	
165	
166						if (proceduraId > 0  && subOrganizationId > 0) {
167							procedura = proceduraLocalService.getProcedura(proceduraId);
168	
169							User userRichiesta = userLocalService.getUserByScreenName(richiesta.getCompanyId(), richiesta.getCodiceFiscale().toLowerCase());
170	
171							PrincipalThreadLocal.setName(userRichiesta.getUserId());
172							PermissionChecker permissionChecker = PermissionCheckerFactoryUtil.create(userRichiesta);
173							PermissionThreadLocal.setPermissionChecker(permissionChecker);
174	
175							Serializable codiceIPACustomAttribute = siteOrganization.getExpandoBridge().getAttribute(OrganizationCustomAttributes.CODICE_IPA.getNomeAttributo());
176	
177							String codiceIPA = null;
178							if (codiceIPACustomAttribute != null) {
179								codiceIPA = (String) codiceIPACustomAttribute;
180							}
181	
182							long processoId = procedura.getProcessoId();
183							if (procedura != null && procedura.isAttiva() && processoId != 0) {
184	
185								// Avvio istanza processo
186	
187								Processo processo = processoLocalService.getProcesso(processoId);
188	
189								if (processo != null && processo.isAttivo()) {
190	
191									Servizio servizio = servizioLocalService.getServizioById(procedura.getServizioId());
192	
193									String candidateGroup = String.valueOf(subOrganizationId);
194									boolean existsGroup = camundaClient.existsGroup(candidateGroup);
195									if (!existsGroup) {
196										throw new Exception("Impossibile assegnare il Gruppo Destinatario.");
197									}
198	
199									// Allegati
200									String allegatiJson = "";
201									List<AllegatoRichiesta> allegatiRichiesta = allegatoRichiestaLocalService.getAllegatiRichiestaByRichiestaId(richiesta.getRichiestaId());
202									List<FileAllegato> datiFileAllegati = getAllegati(allegatiRichiesta);
203									if (datiFileAllegati != null) {
204										allegatiJson = objectMapper.writerWithDefaultPrettyPrinter().writeValueAsString(datiFileAllegati);
205									}
206	
207									// PDF principale
208									String pdfFirmatoJson = "";
209									List<AllegatoRichiesta> allegatiRichiestaByRichiestaIdPrincipale = allegatoRichiestaLocalService.getAllegatiRichiestaByRichiestaIdPrincipale(richiesta.getRichiestaId(),
210											true);
211	
212									if (allegatiRichiestaByRichiestaIdPrincipale != null && !allegatiRichiestaByRichiestaIdPrincipale.isEmpty()) {
213										AllegatoRichiesta allegatoPrincipaleRichiesta = allegatiRichiestaByRichiestaIdPrincipale.get(0);
214										FileAllegato allegatoPrincipale = getAllegatoPrincipale(allegatoPrincipaleRichiesta);
215										if (allegatoPrincipale != null) {
216											pdfFirmatoJson = objectMapper.writerWithDefaultPrettyPrinter().writeValueAsString(allegatoPrincipale);
217										}
218									}
219	
220									Map<String, Object> variables = new HashMap<String, Object>();
221									variables.put(CustomProcessVariables.ID_RICHIESTA_SERVIZIO, richiesta.getRichiestaId());
222									variables.put(CustomProcessVariables.ID_GRUPPO_REFERENTI, candidateGroup);
223	
224									variables.put(CustomProcessVariables.DENOMINAZIONE_RICHIEDENTE, userRichiesta.getFullName());
225									variables.put(CustomProcessVariables.COD_FISCALE_RICHIEDENTE, richiesta.getCodiceFiscale().toUpperCase());
226									variables.put(CustomProcessVariables.EMAIL_RICHIEDENTE, richiesta.getEmail());
227									variables.put(CustomProcessVariables.PARTITA_IVA_RICHIEDENTE, richiesta.getPartitaIva());
228	
229									variables.put(CustomProcessVariables.OGGETTO, richiesta.getOggetto());
230	
231									variables.put(CustomProcessVariables.FILE_ALLEGATI, allegatiJson);
232									variables.put(CustomProcessVariables.NOME_FILE_FIRMATO, ALLEGATO_PDF_FIRMATO);
233									variables.put(CustomProcessVariables.PDF_FIRMATO, pdfFirmatoJson);
234	
235									variables.put(CustomProcessVariables.CODICE_IPA_COMUNE, codiceIPA);
236									variables.put(CustomProcessVariables.DENOMINAZIONE_COMUNE, siteOrganization.getName());
237	
238									variables.put(CustomProcessVariables.CODICE_SERVIZIO, servizio.getCodice());
239									variables.put(CustomProcessVariables.DENOMINAZIONE_SERVIZIO, servizio.getNome());
240	
241									variables.put(CustomProcessVariables.CODICE_AREA_TEMATICA, servizio.getAreaTematica().getCodice());
242									variables.put(CustomProcessVariables.DENOMINAZIONE_AREA_TEMATICA, servizio.getAreaTematica().getNome());
243	
244									variables.put(CustomProcessVariables.DATA_CREAZIONE_RICHIESTA, richiesta.getCreateDate());
245									variables.put(CustomProcessVariables.STATO_RICHIESTA, richiesta.getStato());
246	
247									variables.put(CustomProcessVariables.DATA_CREAZIONE_RICHIESTA_SEARCH, richiesta.getCreateDate().getTime());
248	
249									Date dataInvio = richiesta.getDataInvio();
250									if (dataInvio == null) {
251										dataInvio = richiesta.getModifiedDate();
252									}
253	
254									variables.put(CustomProcessVariables.DATA_INVIO_RICHIESTA, dataInvio);
255									variables.put(CustomProcessVariables.DATA_INVIO_RICHIESTA_SEARCH, dataInvio.getTime());
256									variables.put(CustomProcessVariables.INVIO_GUEST, String.valueOf(richiesta.getInvioGuest()));
257	
258									List<RichiestaDatoAggiuntivo> datoAggiuntivoList = richiestaDatoAggiuntivoLocalService.getByRichiestaId(richiesta.getRichiestaId());
259									if(Validator.isNotNull(datoAggiuntivoList) && !datoAggiuntivoList.isEmpty()){
260										for(RichiestaDatoAggiuntivo datoAggiuntivo : datoAggiuntivoList){
261											variables.put(datoAggiuntivo.getChiaveDato(), datoAggiuntivo.getValoreDato());
262										}
263									}
264	
265									String processDefinitionTenantId = tenantId;
266	
267									boolean isBackofficeMainSiteProcess = siteUtility.isBackofficeMainSite(processo.getGroupId(), processo.getCompanyId());
268	
269									if (isBackofficeMainSiteProcess) {
270										processDefinitionTenantId = null;
271									}
272									String processInstanceId = camundaClient.startProcessInstance(tenantId, processDefinitionTenantId, processo.getCodice(), String.valueOf(businessKey), variables);
273									richiestaLocalService.updateProcessiInstanceIdRichiesta(richiesta.getRichiestaId(), processInstanceId);
274	
275									// Aggiornamento stato in INVIATA se la richiesta è ancora in stato
276									// NUOVA
277									Richiesta richiestaAggiornata = richiestaLocalService.getRichiesta(richiesta.getRichiestaId());
278									if (richiestaAggiornata.getStato().equals(StatoRichiesta.NUOVA.name())) {
279										richiestaLocalService.updateStatoRichiesta(richiesta.getRichiestaId(), StatoRichiesta.INVIATA.name());
280										camundaClient.updateProcessInstanceVariableByBusinessKey(processInstanceId, CustomProcessVariables.STATO_RICHIESTA, StatoRichiesta.INVIATA.name(),
281												CustomProcessVariables.TYPE_STRING);
282									}
283								}
284							}
285							else {
286								// Cambio stato in INVIATA
287								richiestaLocalService.updateStatoRichiesta(richiesta.getRichiestaId(), StatoRichiesta.INVIATA.name());
288							}
289						}
290	
291					}
292					catch (Exception e) {
293						_log.error("Impossibile avviare il processo con ID: " + richiesta.getRichiestaId(), e);
294						throw new KosmosException();
295					}
296				}
297			}
298		}
