348		@Activate
349		@Modified
350		protected void activate(Map<String, Object> properties) throws SchedulerException {
351	
352			// extract the cron expression from the properties
353			try {
354				avvioIstanzaProcessoSchedulerConfiguration = ConfigurableUtil.createConfigurable(IstanzaProcessoSchedulerConfiguration.class, properties);
355				camundaConfiguration = ConfigurableUtil.createConfigurable(CamundaConfiguration.class, properties);
356	
357				if (!avvioIstanzaProcessoSchedulerConfiguration.avvioIstanzaProcessoSchedulerEnabled()) {
358					_log.info("Diattivazione scheduler " + this.getClass().getSimpleName());
359					deactivate();
360					return;
361				}
362	
363				String cronExpression = avvioIstanzaProcessoSchedulerConfiguration.avvioIstanzaProcessoSchedulerCronExpression();
364	
365				_log.info("Attivazione scheduler " + this.getClass().getSimpleName() + " - cronExpression: " + cronExpression);
366	
367				// create a new trigger definition for the job.
368				String listenerClass = getClass().getName();
369				Trigger jobTrigger = _triggerFactory.createTrigger(listenerClass, listenerClass, new Date(), null, cronExpression);
370	
371				// wrap the current scheduler entry in our new wrapper.
372				// use the persisted storaget type and set the wrapper back to the class field.
373				_schedulerEntryImpl = new SchedulerEntryImpl(getClass().getName(), jobTrigger);
374	
375				// if we were initialized (i.e. if this is called due to CA modification)
376				if (_initialized) {
377					// first deactivate the current job before we schedule.
378					deactivate();
379				}
380	
381				// register the scheduled task
382				_schedulerEngineHelper.register(this, _schedulerEntryImpl, DestinationNames.SCHEDULER_DISPATCH);
383	
384				// set the initialized flag.
385				_initialized = true;
386			}
387			catch (Exception e) {
388				_log.error(e);
389				deactivate();
390			}
391		}
392	
393		@Deactivate
394		protected void deactivate() {
395			// if we previously were initialized
396			if (_initialized) {
397				// unschedule the job so it is cleaned up
398				try {
399					_schedulerEngineHelper.unschedule(_schedulerEntryImpl, getStorageType());
400				}
401				catch (SchedulerException se) {
402					if (_log.isWarnEnabled()) {
403						_log.warn("Unable to unschedule trigger", se);
404					}
405				}
406	
407				// unregister this listener
408				_schedulerEngineHelper.unregister(this);
409			}
410	
411			// clear the initialized flag
412			_initialized = false;
413		}
